<script setup lang="ts">
import type { CrmShipmentListItemDto } from '@/api'
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { createPageRequest, CrmShipmentStatus, crmShipmentApi } from '@/api'
import { toast } from '~/composables'
import { usePermission } from '~/hooks'
defineOptions({ name: 'CrmShipmentPage' })
const {t}=useI18n();const {hasPermission}=usePermission()
const rows=ref<CrmShipmentListItemDto[]>([]);const loading=ref(false);const keyword=ref('');const status=ref<CrmShipmentStatus|''>('');const pageIndex=ref(1);const totalCount=ref(0);const pageSize=20;const totalPages=computed(()=>Math.max(1,Math.ceil(totalCount.value/pageSize)));const canCreate=computed(()=>hasPermission('crm_shipments.create'));const canExecute=computed(()=>hasPermission('crm_shipments.execute'))
const createOpen=ref(false);const saving=ref(false);const form=ref({shipmentNumber:'',salesOrderId:'',salesOrderLineId:'',quantity:'1',carrier:'',trackingNumber:''})
async function loadPage(){loading.value=true;try{const p=createPageRequest({page:{pageIndex:pageIndex.value,pageSize}});const r=await crmShipmentApi.page({...p,keyword:keyword.value.trim()||null,status:status.value===''?null:status.value});rows.value=r.items;totalCount.value=r.page.totalCount}catch(e){toast.danger((e as Error)?.message||t('crm.shipment.loadError'))}finally{loading.value=false}}
async function createShipment(){const qty=Number(form.value.quantity);if(!form.value.shipmentNumber.trim()||!form.value.salesOrderId.trim()||!form.value.salesOrderLineId.trim()||!Number.isFinite(qty)||qty<=0){toast.warning(t('crm.shipment.required'));return}saving.value=true;try{await crmShipmentApi.create({shipmentNumber:form.value.shipmentNumber.trim(),salesOrderId:form.value.salesOrderId.trim(),carrier:form.value.carrier.trim()||null,trackingNumber:form.value.trackingNumber.trim()||null,lines:[{salesOrderLineId:form.value.salesOrderLineId.trim(),quantity:qty}]});toast.success(t('crm.shipment.created'));createOpen.value=false;await loadPage()}catch(e){toast.danger((e as Error)?.message||t('crm.shipment.saveError'))}finally{saving.value=false}}
async function changeStatus(row:CrmShipmentListItemDto,next:CrmShipmentStatus){try{await crmShipmentApi.changeStatus({id:row.basicId,status:next});toast.success(t('crm.shipment.statusSaved'));await loadPage()}catch(e){toast.danger((e as Error)?.message||t('crm.shipment.statusError'))}}
function label(s:number){return t(`crm.shipment.status${s}`)}
onMounted(loadPage)
</script>
<template><main class="crm-workflow-page"><header class="page-header"><div><h1>{{t('crm.shipment.title')}}</h1><p>{{t('crm.shipment.description')}}</p></div><button v-if="canCreate" class="primary-button" @click="createOpen=true">{{t('crm.shipment.create')}}</button></header><section class="toolbar"><input v-model="keyword" :placeholder="t('crm.shipment.search')" @keydown.enter="pageIndex=1;loadPage()"><select v-model="status"><option value="">{{t('crm.shipment.allStatuses')}}</option><option v-for="s in [0,1,2,3]" :key="s" :value="s">{{label(s)}}</option></select><button @click="pageIndex=1;loadPage()">{{t('crm.shipment.query')}}</button><button :disabled="loading" @click="loadPage">{{t('crm.shipment.refresh')}}</button></section><section class="table-wrap"><div v-if="loading&&!rows.length" class="empty">{{t('crm.shipment.loading')}}</div><div v-else-if="!rows.length" class="empty">{{t('crm.shipment.empty')}}</div><table v-else><thead><tr><th>{{t('crm.shipment.number')}}</th><th>{{t('crm.shipment.orderId')}}</th><th>{{t('crm.shipment.status')}}</th><th>{{t('crm.shipment.carrier')}}</th><th>{{t('crm.shipment.tracking')}}</th><th>{{t('crm.shipment.shippedAt')}}</th><th>{{t('crm.shipment.deliveredAt')}}</th><th>{{t('crm.shipment.actions')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.basicId"><td>{{row.shipmentNumber}}</td><td>{{row.salesOrderId}}</td><td>{{label(row.status)}}</td><td>{{row.carrier||'—'}}</td><td>{{row.trackingNumber||'—'}}</td><td>{{row.shipmentDate?new Date(row.shipmentDate).toLocaleString():'—'}}</td><td>{{row.deliveredDate?new Date(row.deliveredDate).toLocaleString():'—'}}</td><td class="actions"><button v-if="canExecute&&row.status===CrmShipmentStatus.Draft" @click="changeStatus(row,CrmShipmentStatus.Dispatched)">{{t('crm.shipment.dispatch')}}</button><button v-if="canExecute&&row.status===CrmShipmentStatus.Draft" @click="changeStatus(row,CrmShipmentStatus.Cancelled)">{{t('crm.shipment.cancelDraft')}}</button><button v-if="canExecute&&row.status===CrmShipmentStatus.Dispatched" @click="changeStatus(row,CrmShipmentStatus.Delivered)">{{t('crm.shipment.deliver')}}</button></td></tr></tbody></table></section><footer class="pagination"><span>{{t('crm.shipment.totalCount',{count:totalCount})}} · {{t('crm.shipment.page',{current:pageIndex,total:totalPages})}}</span><div><button :disabled="pageIndex<=1||loading" @click="pageIndex--;loadPage()">{{t('crm.shipment.previous')}}</button><button :disabled="pageIndex>=totalPages||loading" @click="pageIndex++;loadPage()">{{t('crm.shipment.next')}}</button></div></footer><div v-if="createOpen" class="modal-backdrop" @click.self="createOpen=false"><section class="editor"><header><h2>{{t('crm.shipment.newTitle')}}</h2><button @click="createOpen=false">×</button></header><form @submit.prevent="createShipment"><label>{{t('crm.shipment.number')}} *<input v-model="form.shipmentNumber" required maxlength="40"></label><label>{{t('crm.shipment.orderId')}} *<input v-model="form.salesOrderId" required inputmode="numeric"></label><label>{{t('crm.shipment.orderLineId')}} *<input v-model="form.salesOrderLineId" required inputmode="numeric"></label><label>{{t('crm.shipment.quantity')}} *<input v-model="form.quantity" type="number" min="0.0001" step="0.0001" required></label><label>{{t('crm.shipment.carrier')}}<input v-model="form.carrier" maxlength="100"></label><label>{{t('crm.shipment.tracking')}}<input v-model="form.trackingNumber" maxlength="120"></label><footer><button type="button" @click="createOpen=false">{{t('crm.shipment.cancel')}}</button><button class="primary-button" type="submit" :disabled="saving">{{saving?t('crm.shipment.saving'):t('crm.shipment.save')}}</button></footer></form></section></div></main></template>
<style scoped>
.crm-workflow-page{display:flex;flex-direction:column;gap:16px;min-height:100%;padding:20px;color:hsl(var(--foreground))}.page-header,.toolbar,.pagination,.editor header,.editor footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.page-header h1,.editor h2{margin:0;font-size:20px}.page-header p{margin:5px 0 0;color:hsl(var(--muted-foreground));font-size:12px}button,input,select{font:inherit}button{border:1px solid hsl(var(--border));border-radius:7px;padding:7px 11px;background:hsl(var(--card));cursor:pointer}.primary-button{background:hsl(var(--primary));color:hsl(var(--primary-foreground))}.toolbar{justify-content:flex-start;flex-wrap:wrap}.toolbar input,.toolbar select,.editor input{border:1px solid hsl(var(--border));border-radius:7px;padding:8px 10px;background:hsl(var(--card));color:inherit}.table-wrap{overflow:auto;border:1px solid hsl(var(--border));border-radius:10px;background:hsl(var(--card))}table{width:100%;border-collapse:collapse;min-width:950px;text-align:left;font-size:13px}th,td{padding:11px 12px;border-bottom:1px solid hsl(var(--border))}th{color:hsl(var(--muted-foreground));font-size:11px}.actions{white-space:nowrap}.actions button{margin-right:4px;font-size:11px}.empty{padding:44px;text-align:center;color:hsl(var(--muted-foreground))}.pagination{font-size:12px;color:hsl(var(--muted-foreground))}.pagination div{display:flex;gap:6px}.modal-backdrop{position:fixed;z-index:1000;inset:0;display:grid;place-items:center;padding:20px;background:rgb(0 0 0 / 42%)}.editor{width:min(720px,100%);max-height:90vh;overflow:auto;border:1px solid hsl(var(--border));border-radius:12px;padding:20px;background:hsl(var(--card))}.editor form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;margin-top:18px}.editor label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:hsl(var(--muted-foreground))}.editor label input{box-sizing:border-box;width:100%;color:hsl(var(--foreground))}.editor form footer{grid-column:1/-1;justify-content:flex-end}@media(max-width:680px){.crm-workflow-page{padding:12px}.editor form{grid-template-columns:1fr}.editor form footer{grid-column:auto}}
</style>
